public class ContextBudget
{
    public int TotalWindow { get; init; } = 128_000;
    public int ReservedForResponse { get; init; } = 4_000;
    public int SystemPromptTokens { get; init; } = 800;
    public int MaxHistoryTokens { get; init; } = 8_000;

    // Clamped at zero: a misconfigured budget should degrade to "no retrieval",
    // not to a negative number that silently breaks downstream arithmetic.
    public int AvailableForRetrieval => Math.Max(0,
        TotalWindow - ReservedForResponse - SystemPromptTokens - MaxHistoryTokens);

    public int MaxChunks(int tokensPerChunk) =>
        tokensPerChunk <= 0 ? 0 : AvailableForRetrieval / tokensPerChunk;

    public decimal EstimateCostUsd(
        int inputTokens, int outputTokens,
        decimal inputPerMillion, decimal outputPerMillion) =>
        inputTokens / 1_000_000m * inputPerMillion +
        outputTokens / 1_000_000m * outputPerMillion;
}

