public class LlmRetryPolicy
{
    private readonly int _maxAttempts;

    public LlmRetryPolicy(int maxAttempts = 3) => _maxAttempts = maxAttempts;

    public bool ShouldRetry(HttpResponseMessage response, int attempt)
    {
        if (attempt >= _maxAttempts) return false;

        // 429 and 5xx are transient. Every other 4xx is a bad request that will
        // fail identically on retry — and be charged identically.
        return response.StatusCode == HttpStatusCode.TooManyRequests
               || (int)response.StatusCode >= 500;
    }

    public TimeSpan GetDelay(HttpResponseMessage response, int attempt)
    {
        // The server's own guidance beats any backoff we invent.
        if (response.Headers.RetryAfter?.Delta is { } delta) return delta;
        if (response.Headers.RetryAfter?.Date is { } date)
        {
            var wait = date - DateTimeOffset.UtcNow;
            if (wait > TimeSpan.Zero) return wait;
        }

        // Exponential backoff with full jitter: without the random component,
        // every throttled client retries at the same instant.
        var baseDelay = TimeSpan.FromSeconds(Math.Pow(2, attempt));
        var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000));
        return baseDelay + jitter;
    }
}

