[HttpPost("stream")]
public async Task StreamAsync([FromBody] ChatRequest request, CancellationToken ct)
{
    Response.Headers.ContentType = "text/event-stream";
    Response.Headers.CacheControl = "no-cache";
    Response.Headers["X-Accel-Buffering"] = "no";

    var accumulated = new StringBuilder();
    var usage = TokenUsage.Empty;

    try
    {
        // RequestAborted fires when the tab closes: generation stops and so does the cost.
        await foreach (var chunk in _chat.StreamAsync(request, HttpContext.RequestAborted))
        {
            if (chunk.Kind == ChunkKind.Content)
            {
                accumulated.Append(chunk.Text);
                await WriteEventAsync("token", new { text = chunk.Text });
            }
            else if (chunk.Kind == ChunkKind.Usage)
            {
                usage = chunk.Usage!;
            }
        }

        await WriteEventAsync("done", new { costUsd = usage.EstimatedCostUsd });
    }
    catch (OperationCanceledException)
    {
        _logger.LogInformation("Stream cancelled after {Chars} characters", accumulated.Length);
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Stream failed mid-generation");
        // The 200 is already on the wire, so the failure has to be an event.
        await WriteEventAsync("error", new { message = "Generation failed. Partial response shown." });
    }
    finally
    {
        if (accumulated.Length > 0)
            await _conversations.AppendAssistantMessageAsync(
                request.ConversationId, accumulated.ToString(), usage, CancellationToken.None);
    }
}

private async Task WriteEventAsync(string name, object payload)
{
    await Response.WriteAsync($"event: {name}\n");
    await Response.WriteAsync($"data: {JsonSerializer.Serialize(payload)}\n\n");
    await Response.Body.FlushAsync();   // flush every chunk or nothing streams
}

