public class StructureAwareChunker(ITokenCounter tokens) : IChunker
{
    private const int TargetTokens = 300;
    private const int MaxTokens = 450;
    private const int OverlapTokens = 40;

    public IEnumerable<Chunk> Split(ParsedDocument document)
    {
        var index = 0;

        foreach (var section in document.Sections)
        {
            // "Handbook > Leave > Parental Leave" restores the context a
            // mid-document chunk otherwise loses entirely.
            var headingPath = string.Join(" > ", section.HeadingPath);
            var prefix = $"{headingPath}\n\n";
            var prefixTokens = tokens.Count(prefix);

            // Tables never go through the text splitter.
            if (section.IsTable)
            {
                yield return new Chunk(index++, prefix + section.Text, headingPath, section.Page, ChunkKind.Table);
                continue;
            }

            var buffer = new StringBuilder();
            var bufferTokens = 0;

            foreach (var paragraph in section.Paragraphs)
            {
                var paragraphTokens = tokens.Count(paragraph);

                if (bufferTokens + paragraphTokens + prefixTokens > TargetTokens && bufferTokens > 0)
                {
                    var text = buffer.ToString();
                    yield return new Chunk(index++, prefix + text, headingPath, section.Page, ChunkKind.Text);

                    // Overlap keeps a boundary-spanning answer retrievable.
                    var tail = TakeLastTokens(text, OverlapTokens);
                    buffer.Clear().Append(tail).Append("\n\n");
                    bufferTokens = tokens.Count(tail);
                }

                buffer.Append(paragraph).Append("\n\n");
                bufferTokens += paragraphTokens;
            }

            if (bufferTokens > 0)
                yield return new Chunk(index++, prefix + buffer.ToString(), headingPath, section.Page, ChunkKind.Text);
        }
    }

    private string TakeLastTokens(string text, int count)
    {
        var words = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        // Roughly 0.75 words per token for English prose.
        var take = Math.Min(words.Length, (int)(count * 0.75));
        return string.Join(' ', words[^take..]);
    }
}

