public class RankFusion
{
    private const int K = 60;

    public IReadOnlyList<SearchHit> Fuse(
        IReadOnlyList<SearchHit> vectorHits,
        IReadOnlyList<SearchHit> keywordHits,
        double vectorWeight,
        double keywordWeight,
        int topK)
    {
        var scores = new Dictionary<string, double>();
        var byId = new Dictionary<string, SearchHit>();

        // Rank, not score: BM25 is unbounded and corpus-dependent while cosine
        // is bounded and clusters narrowly. Positions are directly comparable.
        for (var i = 0; i < vectorHits.Count; i++)
        {
            var hit = vectorHits[i];
            scores[hit.Id] = scores.GetValueOrDefault(hit.Id) + vectorWeight / (K + i + 1);
            byId[hit.Id] = hit;
        }

        for (var i = 0; i < keywordHits.Count; i++)
        {
            var hit = keywordHits[i];
            scores[hit.Id] = scores.GetValueOrDefault(hit.Id) + keywordWeight / (K + i + 1);
            if (!byId.TryGetValue(hit.Id, out _)) byId[hit.Id] = hit;
        }

        return scores
            .OrderByDescending(kv => kv.Value)
            .Take(topK)
            .Select(kv => byId[kv.Key] with { Score = kv.Value })
            .ToList();
    }
}

