public async Task<AgentResult> RunAsync(AgentRequest request, CancellationToken ct)
{
    using var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct);
    timeout.CancelAfter(request.Timeout);

    var messages = new List<LlmMessage> { new(MessageRole.User, request.Objective) };
    var costSoFar = 0m;
    var seenCalls = new HashSet<string>();

    for (var step = 1; step <= request.MaxSteps; step++)
    {
        var response = await _llm.CompleteAsync(new LlmRequest
        {
            SystemPrompt = request.SystemPrompt,
            Messages = messages,
            Tools = request.Tools.Select(t => t.Definition).ToList()
        }, timeout.Token);

        costSoFar += response.Usage.EstimatedCostUsd;

        // Checked here, not at the end: a runaway loop must be stopped while
        // it is running, not accounted for afterwards.
        if (costSoFar > request.MaxCostUsd)
            return AgentResult.Stopped("Cost ceiling reached.", messages, costSoFar);

        if (response.ToolCalls.Count == 0)
            return AgentResult.Completed(response.Content, messages, costSoFar);

        messages.Add(new LlmMessage(MessageRole.Assistant, response.Content, response.ToolCalls));

        foreach (var call in response.ToolCalls)
        {
            var signature = $"{call.Name}:{call.Arguments.GetRawText()}";

            if (!seenCalls.Add(signature))
            {
                // Saying so explicitly breaks the loop far more often than
                // silently allowing the repeat.
                messages.Add(LlmMessage.ToolResult(call.Id,
                    "You already made this exact call and received the same result. " +
                    "Try a different approach or report what you have found."));
                continue;
            }

            var result = await _executor.ExecuteAsync(call, timeout.Token);
            messages.Add(LlmMessage.ToolResult(call.Id, result.Serialise()));
        }
    }

    return AgentResult.Stopped("Step limit reached without completion.", messages, costSoFar);
}

