@Injectable({ providedIn: 'root' })
export class ChatStreamService {
  private readonly baseUrl = inject(API_BASE_URL);

  stream(conversationId: string, message: string): Observable<string> {
    return new Observable<string>(observer => {
      const controller = new AbortController();

      fetch(`${this.baseUrl}/chat/stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ conversationId, message }),
        signal: controller.signal,
      })
        .then(async response => {
          if (!response.ok || !response.body) {
            observer.error(new Error(`Stream failed with ${response.status}`));
            return;
          }

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = '';

          while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });
            const events = buffer.split('\n\n');
            buffer = events.pop() ?? '';

            for (const raw of events) {
              const nameLine = raw.split('\n').find(l => l.startsWith('event: '));
              const dataLine = raw.split('\n').find(l => l.startsWith('data: '));
              if (!nameLine || !dataLine) continue;

              const name = nameLine.slice(7).trim();
              const payload = JSON.parse(dataLine.slice(6));

              if (name === 'token') observer.next(payload.text);
              // The server cannot change the status after a 200, so a failure
              // arrives as an event and must become a stream error here.
              else if (name === 'error') observer.error(new Error(payload.message));
              else if (name === 'done') observer.complete();
            }
          }

          observer.complete();
        })
        .catch(err => {
          if (err.name !== 'AbortError') observer.error(err);
        });

      // Teardown: aborting closes the connection, which fires RequestAborted
      // on the server and stops generation — and stops the cost.
      return () => controller.abort();
    });
  }
}

