var builder = WebApplication.CreateBuilder(args);

// Resolves to the user-assigned managed identity in Azure, and to the
// developer's az login / Visual Studio credentials locally. One code path,
// no secret in either environment.
var credential = new DefaultAzureCredential(new DefaultAzureCredentialOptions
{
    ManagedIdentityClientId = builder.Configuration["Azure:UserAssignedClientId"]
});

// Key Vault holds only genuine third-party secrets. Reaching it with the
// managed identity means there is no bootstrap secret to protect.
builder.Configuration.AddAzureKeyVault(
    new Uri($"https://{builder.Configuration["Azure:KeyVaultName"]}.vault.azure.net/"),
    credential);

builder.Services.AddSingleton(new AzureOpenAIClient(
    new Uri(builder.Configuration["AzureOpenAI:Endpoint"]!), credential));

builder.Services.AddSingleton(new SearchClient(
    new Uri(builder.Configuration["Search:Endpoint"]!),
    builder.Configuration["Search:Index"]!,
    credential));

var app = builder.Build();

