resource "azurerm_cognitive_account" "openai" {
  name                          = "aoai-prod"
  location                      = var.location
  resource_group_name           = var.resource_group_name
  kind                          = "OpenAI"
  sku_name                      = "S0"
  custom_subdomain_name         = "aoai-prod"   # required for private endpoints
  public_network_access_enabled = false
}

resource "azurerm_private_endpoint" "openai" {
  name                = "pe-aoai-prod"
  location            = var.location
  resource_group_name = var.resource_group_name
  subnet_id           = var.private_subnet_id

  private_service_connection {
    name                           = "psc-aoai-prod"
    private_connection_resource_id = azurerm_cognitive_account.openai.id
    subresource_names              = ["account"]
    is_manual_connection           = false
  }

  private_dns_zone_group {
    name                 = "default"
    private_dns_zone_ids = [azurerm_private_dns_zone.openai.id]
  }
}

# Without this zone the hostname resolves to the public IP and traffic keeps
# taking the internet path — the endpoint exists and does nothing.
resource "azurerm_private_dns_zone" "openai" {
  name                = "privatelink.openai.azure.com"
  resource_group_name = var.resource_group_name
}

resource "azurerm_private_dns_zone_virtual_network_link" "openai" {
  name                  = "link-aoai-prod"
  resource_group_name   = var.resource_group_name
  private_dns_zone_name = azurerm_private_dns_zone.openai.name
  virtual_network_id    = var.vnet_id
}

# Data-plane access by identity, so there is no key to rotate or leak.
resource "azurerm_role_assignment" "orchestrator_openai" {
  scope                = azurerm_cognitive_account.openai.id
  role_definition_name = "Cognitive Services OpenAI User"
  principal_id         = var.orchestrator_identity_principal_id
}
